    ((((((((((c_6_1_1__m6) + (c_6_2_1__m6))) + (c_6_3_1__m6))) + (c_6_4_1__m6))) + (c_6_5_1__m6))) + (c_6_6_1__m6)) AS c_6_7_1__m6,
    ((c_7_1__d7) + (c_7_2__d7)) AS c_7__d7,
    ((c_7_1__d15) + (c_7_2__d15)) AS c_7__d15,
    ((c_7_1__d30) + (c_7_2__d30)) AS c_7__d30,
    ((c_7_1__m2) + (c_7_2__m2)) AS c_7__m2,
    ((c_7_1__m3) + (c_7_2__m3)) AS c_7__m3,
    ((c_7_1__m4) + (c_7_2__m4)) AS c_7__m4,
    ((c_7_1__m5) + (c_7_2__m5)) AS c_7__m5,
    ((c_7_1__m6) + (c_7_2__m6)) AS c_7__m6,
    ((((((((((((((c_7_1__d7) + (c_7_1__d15))) + (c_7_1__d30))) + (c_7_1__m2))) + (c_7_1__m3))) + (c_7_1__m4))) + (c_7_1__m5))) + (c_7_1__m6)) AS c_7_1__total,
    ((((((((((((((c_7_2__d7) + (c_7_2__d15))) + (c_7_2__d30))) + (c_7_2__m2))) + (c_7_2__m3))) + (c_7_2__m4))) + (c_7_2__m5))) + (c_7_2__m6)) AS c_7_2__total
    FROM layer_0
  ),
  layer_2 AS (
    SELECT
      layer_1.*,
    (CASE WHEN ((c_1_1__prior) = (CAST(0 AS DECIMAL(38, 10)))) THEN CAST(0 AS DECIMAL(38, 10)) ELSE ((((CAST(100 AS DECIMAL(38, 10))) * (c_1_1__change))) / NULLIF((c_1_1__prior), 0)) END) AS c_1_1__change_pct,
    (CASE WHEN ((c_1_2__prior) = (CAST(0 AS DECIMAL(38, 10)))) THEN CAST(0 AS DECIMAL(38, 10)) ELSE ((((CAST(100 AS DECIMAL(38, 10))) * (c_1_2__change))) / NULLIF((c_1_2__prior), 0)) END) AS c_1_2__change_pct,
    (CASE WHEN ((c_1_3__prior) = (CAST(0 AS DECIMAL(38, 10)))) THEN CAST(0 AS DECIMAL(38, 10)) ELSE ((((CAST(100 AS DECIMAL(38, 10))) * (c_1_3__change))) / NULLIF((c_1_3__prior), 0)) END) AS c_1_3__change_pct,
    (CASE WHEN ((c_1_4__prior) = (CAST(0 AS DECIMAL(38, 10)))) THEN CAST(0 AS DECIMAL(38, 10)) ELSE ((((CAST(100 AS DECIMAL(38, 10))) * (c_1_4__change))) / NULLIF((c_1_4__prior), 0)) END) AS c_1_4__change_pct,
    (CASE WHEN ((c_1_5__prior) = (CAST(0 AS DECIMAL(38, 10)))) THEN CAST(0 AS DECIMAL(38, 10)) ELSE ((((CAST(100 AS DECIMAL(38, 10))) * (c_1_5__change))) / NULLIF((c_1_5__prior), 0)) END) AS c_1_5__change_pct,
    ((c_1_6__balance) - (c_1_6__prior)) AS c_1_6__change,
    (CASE WHEN ((c_1_6_1__prior) = (CAST(0 AS DECIMAL(38, 10)))) THEN CAST(0 AS DECIMAL(38, 10)) ELSE ((((CAST(100 AS DECIMAL(38, 10))) * (c_1_6_1__change))) / NULLIF((c_1_6_1__prior), 0)) END) AS c_1_6_1__change_pct,
    (CASE WHEN ((c_2_1__prior) = (CAST(0 AS DECIMAL(38, 10)))) THEN CAST(0 AS DECIMAL(38, 10)) ELSE ((((CAST(100 AS DECIMAL(38, 10))) * (c_2_1__change))) / NULLIF((c_2_1__prior), 0)) END) AS c_2_1__change_pct,
    (CASE WHEN ((c_2_1_1__prior) = (CAST(0 AS DECIMAL(38, 10)))) THEN CAST(0 AS DECIMAL(38, 10)) ELSE ((((CAST(100 AS DECIMAL(38, 10))) * (c_2_1_1__change))) / NULLIF((c_2_1_1__prior), 0)) END) AS c_2_1_1__change_pct,
    (CASE WHEN ((c_2_2__prior) = (CAST(0 AS DECIMAL(38, 10)))) THEN CAST(0 AS DECIMAL(38, 10)) ELSE ((((CAST(100 AS DECIMAL(38, 10))) * (c_2_2__change))) / NULLIF((c_2_2__prior), 0)) END) AS c_2_2__change_pct,
    (CASE WHEN ((c_2_2_1__prior) = (CAST(0 AS DECIMAL(38, 10)))) THEN CAST(0 AS DECIMAL(38, 10)) ELSE ((((CAST(100 AS DECIMAL(38, 10))) * (c_2_2_1__change))) / NULLIF((c_2_2_1__prior), 0)) END) AS c_2_2_1__change_pct,
    (CASE WHEN ((c_2_3__prior) = (CAST(0 AS DECIMAL(38, 10)))) THEN CAST(0 AS DECIMAL(38, 10)) ELSE ((((CAST(100 AS DECIMAL(38, 10))) * (c_2_3__change))) / NULLIF((c_2_3__prior), 0)) END) AS c_2_3__change_pct,
    (CASE WHEN ((c_2_3_1__prior) = (CAST(0 AS DECIMAL(38, 10)))) THEN CAST(0 AS DECIMAL(38, 10)) ELSE ((((CAST(100 AS DECIMAL(38, 10))) * (c_2_3_1__change))) / NULLIF((c_2_3_1__prior), 0)) END) AS c_2_3_1__change_pct,
    (CASE WHEN ((c_2_4__prior) = (CAST(0 AS DECIMAL(38, 10)))) THEN CAST(0 AS DECIMAL(38, 10)) ELSE ((((CAST(100 AS DECIMAL(38, 10))) * (c_2_4__change))) / NULLIF((c_2_4__prior), 0)) END) AS c_2_4__change_pct,
    (CASE WHEN ((c_2_4_1__prior) = (CAST(0 AS DECIMAL(38, 10)))) THEN CAST(0 AS DECIMAL(38, 10)) ELSE ((((CAST(100 AS DECIMAL(38, 10))) * (c_2_4_1__change))) / NULLIF((c_2_4_1__prior), 0)) END) AS c_2_4_1__change_pct,
    (CASE WHEN ((c_2_5__prior) = (CAST(0 AS DECIMAL(38, 10)))) THEN CAST(0 AS DECIMAL(38, 10)) ELSE ((((CAST(100 AS DECIMAL(38, 10))) * (c_2_5__change))) / NULLIF((c_2_5__prior), 0)) END) AS c_2_5__change_pct,
    (CASE WHEN ((c_2_5_1__prior) = (CAST(0 AS DECIMAL(38, 10)))) THEN CAST(0 AS DECIMAL(38, 10)) ELSE ((((CAST(100 AS DECIMAL(38, 10))) * (c_2_5_1__change))) / NULLIF((c_2_5_1__prior), 0)) END) AS c_2_5_1__change_pct,
