    ((((((((((((((((c_6_7_1__at_call) + (c_6_7_1__d7))) + (c_6_7_1__d15))) + (c_6_7_1__d30))) + (c_6_7_1__m2))) + (c_6_7_1__m3))) + (c_6_7_1__m4))) + (c_6_7_1__m5))) + (c_6_7_1__m6)) AS c_6_7_1__total,
    ((((((((((((((c_7__d7) + (c_7__d15))) + (c_7__d30))) + (c_7__m2))) + (c_7__m3))) + (c_7__m4))) + (c_7__m5))) + (c_7__m6)) AS c_7__total
