      layer_2.*,
    (CASE WHEN ((c_1_6__prior) = (CAST(0 AS DECIMAL(38, 10)))) THEN CAST(0 AS DECIMAL(38, 10)) ELSE ((((CAST(100 AS DECIMAL(38, 10))) * (c_1_6__change))) / NULLIF((c_1_6__prior), 0)) END) AS c_1_6__change_pct,
